#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# TradeReady roadmap ship wizard (phases 25 → 18). Every step here is an owner
# step from the phase specs' rollout sections; docs/roadmap-execution-ledger.md
# has the background. Re-run any time: finished stages are remembered in a
# progress file next to this script and offered as skips. No secret is ever
# written to disk by this script.

TOTAL_STAGES=25

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO="$(cd "$SCRIPT_DIR/.." && pwd)"
LEGAL="$(cd "$REPO/.." && pwd)/tradeready-legal"
WORKER="$REPO/backend-workers"
STACK_TOP="feat/tap-to-pay"
SUPABASE_REF="ncbqswfdvckmdocbawaa"
SQL_EDITOR="https://supabase.com/dashboard/project/$SUPABASE_REF/sql/new"
WORKER_BASE="https://tradeready-backend.tradeready.workers.dev"
SITE="https://gettradereadyapp.com"
# The progress file holds only DONE_<stage>=<date> lines, never secrets.
ENV_FILE="$SCRIPT_DIR/.ship-roadmap-progress"
DATABASE_URL="${DATABASE_URL:-}"
DB_CHECKED=""

cd "$REPO"

# begin ID "Name": announce a stage; returns 1 (skip) when it is already done
# and the human doesn't want to repeat it.
begin() {
  stage "$2"
  local when; when=$(_existing "DONE_$1" || true)
  if [[ -n "$when" ]]; then
    note "Already marked done on $when."
    confirm "Run it again?" || return 1
  fi
  return 0
}
mark_done() { write_env "DONE_$1" "$(date +%Y-%m-%d)"; pause "Press Enter for the next stage"; }
# defer "what": leave a gated stage for a later run.
defer() { SKIPPED+=("$1"); warn "Left for a later run: $1"; pause "Press Enter to move on"; }
die() { printf '\n  %s✗ %s%s\n\n' "$RED" "$1" "$RESET"; exit 1; }
run() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; "$@"; }
# commit_if_changed "message" FILE...: commit those files on master when they changed.
commit_if_changed() {
  local msg="$1"; shift
  git add -- "$@"
  if git diff --cached --quiet -- "$@"; then note "No change to commit."; return 0; fi
  git commit -q -m "$msg" -- "$@" || die "git commit failed."
  printf '  %s✓ committed%s %s\n' "$GREEN" "$RESET" "$msg"
}

on_master() {
  local b; b=$(git -C "$REPO" branch --show-current)
  [[ "$b" == "master" ]] || die "This step must run on master (you're on '$b'). Finish stage 2 first."
}
wrangler() { (cd "$WORKER" && npx --no-install wrangler "$@"); }
has_secret() { wrangler secret list --env "" 2>/dev/null | grep -q "\"$1\""; }
# put_secret NAME: generate 48 random bytes and pipe them straight into Wrangler.
put_secret() {
  openssl rand -base64 48 | tr -d '\n' | wrangler secret put "$1" --env "" >/dev/null \
    || die "wrangler secret put $1 failed"
  printf '  %s✓ set%s Worker secret %s\n' "$GREEN" "$RESET" "$1"
}

need_db() {
  [[ -n "$DB_CHECKED" ]] && return 0
  if [[ -z "$DATABASE_URL" ]]; then
    say "The verify scripts run with psql. They roll back and change no data."
    open_url "https://supabase.com/dashboard/project/$SUPABASE_REF"
    step "Click Connect in the top bar and copy a URI connection string."
    step "Replace [YOUR-PASSWORD] in it with the database password."
    ask_secret DATABASE_URL "Paste the connection string (kept in memory only):"
    [[ -n "$DATABASE_URL" ]] || die "No connection string, so the verify scripts can't run."
  else
    note "Using DATABASE_URL from your environment."
  fi
  local err
  if ! err=$(psql "$DATABASE_URL" -Atc 'select 1' 2>&1 >/dev/null); then
    DATABASE_URL=""
    printf '%s\n' "$err" | sed 's/^/    /' | head -6
    die "Couldn't connect with that connection string (wrong password, or try the Session pooler URI)."
  fi
  printf '  %s✓ connected%s\n' "$GREEN" "$RESET"
  if [[ "$DATABASE_URL" != *"$SUPABASE_REF"* ]]; then
    warn "That connection string doesn't contain this project's ref ($SUPABASE_REF)."
    note "Supabase strings for it contain db.$SUPABASE_REF.supabase.co or the user postgres.$SUPABASE_REF."
    if ! confirm "Use it anyway?"; then DATABASE_URL=""; die "Copy the string from project $SUPABASE_REF, then re-run."; fi
  fi
  local info
  info=$(psql "$DATABASE_URL" -Atc "select current_user || ' on ' || current_database() || ' (' || (select count(*) from pg_tables where schemaname = 'public') || ' public tables); public.invoices ' || case when to_regclass('public.invoices') is null then 'MISSING' else 'found' end")
  note "Connected as $info"
  if [[ "$info" == *MISSING ]]; then
    DATABASE_URL=""
    die "No public.invoices table here, so this isn't TradeReady's production database. Use project $SUPABASE_REF's string."
  fi
  DB_CHECKED=1
}
# sql_value "query": one value from a read-only query.
sql_value() { need_db; psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -Atc "$1"; }
verify_sql() {
  need_db
  say "Running $1 ..."
  local log; log=$(mktemp -t ship-verify)
  if psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -q -f "$REPO/$1" >"$log" 2>&1; then
    grep -aE 'PASSED|NOTICE' "$log" | tail -3 | sed 's/^/    /'
    printf '  %s✓ passed%s %s\n' "$GREEN" "$RESET" "$1"
  else
    warn "psql output (full log: $log):"
    grep -av '^[[:space:]]*$' "$log" | tail -12 | sed 's/^/    /'
    die "$1 failed. Don't continue until it passes."
  fi
}
# apply_migration FILE: the human applies it in the SQL editor (the specs' method).
apply_migration() {
  local f="supabase/migrations/$1"
  [[ -f "$REPO/$f" ]] || die "$f isn't in this tree. Are you on master after stage 2?"
  pbcopy < "$REPO/$f"
  say "$f is on your clipboard ($(wc -l < "$REPO/$f" | tr -d ' ') lines)."
  open_url "$SQL_EDITOR"
  step "Paste it into a new SQL editor query and click Run."
  step "It should finish with no error. If it errors, stop here and keep the message."
  confirm "Did it run without errors?" || die "Stopped at $f. Re-run the wizard once it's sorted."
}
# set_toml_var KEY 'TOML value': upsert KEY into the top-level [vars] of wrangler.toml.
set_toml_var() {
  local key="$1" val="$2" toml="$WORKER/wrangler.toml" tmp; tmp=$(mktemp)
  awk -v k="$key" -v line="$key = $val" '
    /^\[/ { invars = ($0 == "[vars]") }
    invars && index($0, k " = ") == 1 { if (!done) print line; done = 1; next }
    { print }
    $0 == "[vars]" && !done { print line; done = 1 }
  ' "$toml" > "$tmp" && mv "$tmp" "$toml"
  printf '  %s✓ set%s %s in backend-workers/wrangler.toml [vars]\n' "$GREEN" "$RESET" "$key"
}
deploy_worker() {
  on_master
  say "Worker tests first:"
  (cd "$WORKER" && npm test >/dev/null 2>&1) || die "npm test failed in backend-workers. Run it there to see why."
  printf '  %s✓%s npm test\n' "$GREEN" "$RESET"
  (cd "$WORKER" && npm run check >/dev/null 2>&1) || die "npm run check (dry-run build) failed."
  printf '  %s✓%s dry-run build\n' "$GREEN" "$RESET"
  confirm "Deploy the Worker to production now?" || die "Not deployed. Re-run when ready."
  (cd "$WORKER" && run npm run deploy) || die "Deploy failed."
}
# legal_publish "message": commit the legal repo's working tree and publish it
# (GitHub Pages serves gettradereadyapp.com from main).
legal_publish() {
  local msg="$1"; shift
  git -C "$LEGAL" add -A -- . "$@"
  if git -C "$LEGAL" diff --cached --quiet; then note "Nothing new to commit in tradeready-legal."; else
    git -C "$LEGAL" commit -q -m "$msg" && printf '  %s✓ committed%s %s\n' "$GREEN" "$RESET" "$msg"
  fi
  local b; b=$(git -C "$LEGAL" branch --show-current)
  confirm "Publish: merge '$b' into main and push to GitHub Pages?" || die "Not published. Re-run when ready."
  if [[ "$b" != "main" ]]; then
    run git -C "$LEGAL" switch -q main
    run git -C "$LEGAL" pull -q --ff-only
    run git -C "$LEGAL" merge -q --no-edit "$b" || die "Merge conflict in tradeready-legal. Resolve, push main, then re-run."
  fi
  run git -C "$LEGAL" push -q origin main || die "Push failed."
  if [[ "$b" != "main" ]]; then run git -C "$LEGAL" switch -q "$b"; fi
  say "GitHub Pages usually updates within a few minutes."
}

banner "TradeReady: ship roadmap phases 25 → 18"

# ── A. Get the code onto master ───────────────────────────────────────────
if begin S01 "Preflight: tools and logins"; then
  for t in git psql openssl npx pbcopy curl; do
    command -v "$t" >/dev/null 2>&1 || die "$t isn't installed."
  done
  command -v initdb >/dev/null 2>&1 || warn "initdb isn't on PATH. Stage 4's local Postgres check needs it (brew install postgresql@16)."
  [[ -d "$LEGAL/.git" ]] || die "Expected the legal site repo at $LEGAL."
  [[ -d "$WORKER/node_modules" ]] || (cd "$WORKER" && run npm ci)
  say "Checking your Cloudflare login:"
  wrangler whoami || die "Run 'npx wrangler login' in backend-workers, then re-run."
  mark_done S01
fi

if begin S02 "Merge the stack into master"; then
  say "$STACK_TOP holds all 13 phases. Everything later deploys from master."
  stale=()
  while IFS= read -r f; do
    git cat-file -e "$STACK_TOP:$f" 2>/dev/null && stale+=("$f")
  done < <(git ls-files --others --exclude-standard -- docs)
  if (( ${#stale[@]} )); then
    warn "These untracked drafts would block the merge. Committed, newer copies are on $STACK_TOP:"
    for f in "${stale[@]}"; do note "  $f"; done
    confirm "Delete the stale drafts?" || die "Move them aside, then re-run."
    rm -- "${stale[@]}"
  fi
  run git fetch -q origin master
  run git switch -q master || die "Couldn't switch to master. Stash or commit local changes, then re-run."
  if ! git merge-base --is-ancestor origin/master HEAD; then
    run git merge -q --ff-only origin/master || die "Local master has diverged from origin/master. Sort that out first."
  fi
  confirm "Merge $STACK_TOP into master (local only, no push)?" || die "Not merged."
  run git merge --no-edit "$STACK_TOP" || die "Merge conflicts. Resolve, commit, then re-run."
  note "Pushing master or opening a PR is up to you; deploys below use this local tree."
  mark_done S02
fi

if begin S03 "E-signature wording sign-off"; then
  say "You approved the autopay, API and calendar wording as drafted (docs/roadmap-owner-decisions-2026-10-03.md)."
  say "On 2026-10-15 you lifted the e-signature lawyer review (19-Q2): the wording is approved as drafted."
  step "E-signature: disclosure, checkbox, intent, footer (backend-workers/lib/esign/texts.js) + terms/privacy (esign spec §11.6)"
  note "Stage 21 asks whether it's back."
  mark_done S03
fi

# ── B. Database ───────────────────────────────────────────────────────────
if begin S04 "Database preflight checks"; then
  on_master
  say "1/2: the invoice-payment merge trigger (autopay, tips and Tap to Pay rely on it)."
  need_db
  idtype=$(sql_value "select format_type(atttypid, atttypmod) from pg_attribute where attrelid = 'public.invoices'::regclass and attname = 'id' and not attisdropped")
  [[ "$idtype" == "text" ]] || die "public.invoices.id is '$idtype', not text. The verify script assumes text ids; stop and check (deposits-resume-here.md §4 step 1)."
  users=$(sql_value "select count(*) from auth.users")
  if [[ "$users" == "0" ]]; then
    warn "auth.users is empty, and the verify script needs one user row to seed its test invoice (it rolls back)."
    step "Create a throwaway account: sign up in the app, or Supabase › Authentication › Users › Add user."
    die "Re-run the wizard once an account exists."
  fi
  trg=$(sql_value "select count(*) from pg_trigger where tgname='merge_invoice_payments_trg' and tgrelid='public.invoices'::regclass and not tgisinternal")
  if [[ "$trg" == "0" ]]; then
    warn "The ledger union trigger isn't on public.invoices: 20260718_invoice_payment_merge.sql was never applied."
    note "It's idempotent and changes no existing row (no production invoice carries a payments key yet)."
    confirm "Apply it now?" || die "Apply supabase/migrations/20260718_invoice_payment_merge.sql, then re-run."
    apply_migration 20260718_invoice_payment_merge.sql
    note "The verify script below must run through psql, never the SQL editor (it relies on one rolled-back transaction)."
  else
    printf '  %s✓%s merge_invoice_payments_trg is present\n' "$GREEN" "$RESET"
  fi
  verify_sql supabase/migrations/verify/20260718_invoice_payment_merge_verify.sql
  say "2/2: the approval-preserve trigger, proven on a throwaway local Postgres (never your real DB)."
  (run sh supabase/verify/job_approval_preserve.sh) || die "job_approval_preserve.sh failed."
  mark_done S04
fi

if begin S05 "Migration: job forms (Phase 20)"; then
