if begin S12 "Account-deletion cascade check"; then
  on_master
  note "Confirms every new user-owned table cascades when an account is deleted."
  verify_sql supabase/verify/account_deletion_cascade.sql
  note "Optional later: add api_keys and api_access_log to that file's expected list (open-api spec §14.8 step 7)."
  mark_done S12
