# ── C. Secrets and the Worker deploy ─────────────────────────────────────
if begin S13 "Worker secrets for the open API"; then
  for name in API_CURSOR_SECRET API_KEY_TAG_SECRET; do
    if has_secret "$name"; then
      note "$name is already set; leaving it alone."
      if [[ "$name" == API_KEY_TAG_SECRET ]]; then note "(Changing it would invalidate every API key.)"; fi
    else
      say "Generating a random value for $name and sending it straight to Cloudflare."
      put_secret "$name"
    fi
  done
  warn "Don't set PAY_LINK_SIGNING_SECRET yet: it switches on pay-page links (stage 17)."
  mark_done S13
fi

if begin S14 "Deploy the Worker"; then
  on_master
  grep -qE '^ESIGN_V2 *=' "$WORKER/wrangler.toml" && die "ESIGN_V2 is set in wrangler.toml; it must stay off for this deploy."
  note "With PAY_LINK_SIGNING_SECRET and ESIGN_V2 unset, this deploy is backward compatible or inert."
  deploy_worker
  mark_done S14
fi

if begin S15 "Stripe Connect webhook"; then
  open_url "https://dashboard.stripe.com/webhooks"
  say "Live mode and the sandbox (test mode) have SEPARATE webhook lists, with a Worker endpoint in each."
  step "Start in LIVE mode. Afterwards, repeat the event edit on the sandbox endpoint (for test-mode Tap to Pay)."
  step "Find the endpoint whose URL is $WORKER_BASE/api/stripe/webhook"
  note "  and that listens to events on Connected accounts (not \"Your account\")."
  if ! confirm "Found exactly that endpoint (Worker URL, Connected accounts)?"; then
    warn "Then card payments may not be reaching the Worker at all."
    note "Setup reference: docs/superpowers/plans/2026-08-05-stripe-live-golive-runbook.md Part 2."
    note "Don't create a new endpoint to fix it without updating STRIPE_CONNECT_WEBHOOK_SECRET:"
    note "the Worker checks every event against that one endpoint's signing secret."
    defer "Stripe webhook endpoint not found (stage 15). Sort it out before stage 17"
  else
    checkout_ok=1
    say "Its event list should already contain checkout.session.completed (every card payment books through it)."
    if ! confirm "Is checkout.session.completed in the list?"; then
      warn "Without it, no card payment is being recorded automatically, and autopay can't activate."
      step "Add checkout.session.completed to THIS endpoint (edit its events), then check its recent deliveries"
      note "  for payments that never arrived; those invoices need marking paid by hand."
      if ! confirm "Added it?"; then
        defer "Add checkout.session.completed to the Connect endpoint (stage 15). Required before stage 17"
        checkout_ok=0
      fi
    fi
    say "payment_intent.succeeded is NOT expected to be there yet. Adding it is this stage's job."
    step "Workbench › Webhooks tab › click this endpoint › edit it (the Edit button or the ... menu)."
    step "In its event list, search payment_intent.succeeded, tick it, keep checkout.session.completed ticked, save."
    step "Then switch to the sandbox and add it to the sandbox Worker endpoint the same way."
    note "Same endpoint, not a new one, so the signing secret stays the same. Tap to Pay needs it before it's ever enabled."
    if confirm "Is payment_intent.succeeded on the live endpoint now (and the sandbox one)?" && (( checkout_ok )); then
      mark_done S15
    else
      defer "Finish the Connect endpoint's events (stage 15)"
    fi
  fi
fi

# ── D. Legal pages ───────────────────────────────────────────────────────
if begin S16 "Publish the legal pages"; then
  say "tradeready-legal has every phase's page edits uncommitted on '$(git -C "$LEGAL" branch --show-current)'."
  git -C "$LEGAL" status --short | sed 's/^/    /'
  if grep -q 'followed by 43 letters' "$LEGAL/developers.html"; then
    warn "developers.html still says keys are trk_ + 43 characters; they're now trk_ + 107."
    if confirm "Fix that line?"; then
      sed -i '' 's/followed by 43 letters/followed by 107 letters/' "$LEGAL/developers.html"
      printf '  %s✓ fixed%s developers.html\n' "$GREEN" "$RESET"
    fi
  fi
  say "The approved wording was applied to terms.html and privacy.html on 2026-10-15 (uncommitted)."
  step "Review it first:  git -C \"$LEGAL\" diff terms.html privacy.html"
  note "Set both pages' effective dates to the day you publish (currently October 15, 2026)."
  note "verify.html is held back until stage 22 (it needs the signing key)."
  note "The e-signature code on estimate.html and change.html stays dormant while ESIGN_V2 is off."
  if confirm "Approved wording is in and you're ready to publish?"; then
    legal_publish "Publish roadmap pages: options, expiry, lead source, referrals, campaigns, pay page, tips, API docs" ':!verify.html'
    open_url "$SITE/developers.html"
    mark_done S16
  else
    defer "Publish legal pages (stage 16; must happen before the app build)"
  fi
fi

if begin S17 "Turn on pay-page links"; then
  if [[ -z "$(_existing DONE_S15 || true)" ]]; then
    defer "Turn on pay-page links (needs stage 15: pay-page payments book through checkout.session.completed)"
  else
  say "PAY_LINK_SIGNING_SECRET switches invoices from Stripe Payment Links to the new pay page."
  open_url "$SITE/terms.html"
  step "The autopay terms must be live first, so autopay never runs under terms that don't describe it."
  if confirm "Are the autopay terms (terms.html §4) live on the site?"; then
    if has_secret PAY_LINK_SIGNING_SECRET; then note "Already set."; else put_secret PAY_LINK_SIGNING_SECRET; fi
    mark_done S17
  else
    defer "Set PAY_LINK_SIGNING_SECRET once the autopay terms are live (stage 17)"
  fi
  fi
fi

# ── E. The native build ──────────────────────────────────────────────────
if begin S18 "API access in the app"; then
  on_master
  f="native/TradeReadyNative/Domain/NativeAPIAccess.swift"
  t="native/APIAccessTests/main.swift"
  say "Settings › API access is compiled out until apiAccessEnabled is true. The Worker is live now."
  if confirm "Turn API access on for this build?"; then
    sed -i '' 's/static let apiAccessEnabled = false/static let apiAccessEnabled = true/' "$f"
    sed -i '' \
      -e 's/apiAccessEnabled == false, "flag: apiAccessEnabled defaults to OFF"/apiAccessEnabled == true, "flag: apiAccessEnabled is ON"/' \
      -e 's/expect(!NativeAPIAccessFeature.showsSettingsEntry(), "flag: off hides the Settings entry")/expect(NativeAPIAccessFeature.showsSettingsEntry(), "flag: on shows the Settings entry")/' \
      -e 's/domain.contains("static let apiAccessEnabled = false"), "flag: the source default is off"/domain.contains("static let apiAccessEnabled = true"), "flag: the source default is on"/' \
      "$t"
    say "Running the API access tests:"
    tmp=$(mktemp -d); ok=1
    out=$(TMPDIR="$tmp/" sh native/run-api-access-tests.sh 2>&1) || ok=0
    printf '%s\n' "$out" | grep -aE 'FAIL|tests passed|error:' | head -8
    if (( ok )); then
      commit_if_changed "feat(open-api): turn on API access in Settings" "$f" "$t"
      note "Optional before archiving: sh native/run-all-domain-tests.sh (the full suite; it takes a while)."
    else
      die "Other tests assume the flag is off. Fix them (or ask Claude to), commit, then re-run."
    fi
  else
    note "Left off. Stage 20's smoke test needs it on, so it will be skipped."
  fi
  mark_done S18
fi

if begin S19 "Ship the native build"; then
  on_master
  say "Release gates (all should be done by now):"
  for s in S04 S05 S06 S07 S08 S16; do
    if [[ -z "$(_existing "DONE_$s" || true)" ]]; then
      warn "Stage $((10#${s#S})) isn't marked done. The build must not ship before it."
    fi
  done
  say "Version 2.0.0 (the native release N; it must stay below the Expo rollback candidate R 2.1.1)."
  say "The build number must be above every earlier upload of the app: native 2.0.0 used 1-3, R used 14."
  step "Check App Store Connect › TestFlight for anything higher than 14 first."
  ask BUILD_NO "Build number for this upload (15 unless TestFlight shows higher):"
  [[ "$BUILD_NO" =~ ^[0-9]+$ ]] || die "Build number must be a whole number."
  say "Dry run (prints the archive, export and upload commands; uploads nothing):"
  sh "$REPO/native/phase-12-testflight-upload.sh" --version 2.0.0 --build "$BUILD_NO" | tail -12 | sed 's/^/    /'
  step "Upload: load ASC_KEY_ID, ASC_ISSUER_ID, ASC_KEY_PATH and TRADEREADY_SENTRY_DSN from your secret store, then run"
  note "  sh native/phase-12-testflight-upload.sh --version 2.0.0 --build $BUILD_NO --execute --i-am-the-owner"
  note "Don't archive from Xcode's menu: it would use build number 1, which App Store Connect already has."
  pause "Press Enter once the upload is processing in App Store Connect"
  open_url "https://appstoreconnect.apple.com/apps"
  step "App Privacy: add the \"Other User Content\" label (docs/native-phase-12-release-readiness.md §5)."
  step "App Review Information: add the calendar-access note (same doc §7)."
  step "Submit through TestFlight and App Review as usual."
  if confirm "Build submitted?"; then mark_done S19; else defer "Ship the native build (stage 19)"; fi
fi

if begin S20 "Open API smoke test"; then
  if ! grep -q 'static let apiAccessEnabled = true' "$REPO/native/TradeReadyNative/Domain/NativeAPIAccess.swift"; then
    defer "API smoke test (needs API access on, stage 18)"
  else
    step "In a build with API access (TestFlight is fine): Settings › API access › create a key with the Everything preset."
    ask_secret API_KEY "Paste the new key (kept in memory only):"
    auth=(-H "Authorization: Bearer $API_KEY")
    say "GET /v1/account:"
    acct=$(curl -fsS "${auth[@]}" "$WORKER_BASE/v1/account") || die "/v1/account failed."
    printf '    %.400s\n' "$acct"
    say "GET /v1/customers?limit=1:"
    page=$(curl -fsS "${auth[@]}" "$WORKER_BASE/v1/customers?limit=1") || die "List call failed."
    printf '    %.400s\n' "$page"
    cursor=$(printf '%s' "$page" | sed -n 's/.*"nextCursor":"\([^"]*\)".*/\1/p')
    if [[ -n "$cursor" ]]; then
      curl -fsS -G "${auth[@]}" "$WORKER_BASE/v1/customers" --data-urlencode "limit=1" --data-urlencode "cursor=$cursor" >/dev/null \
        && printf '  %s✓%s followed nextCursor\n' "$GREEN" "$RESET"
    else
      note "No nextCursor (one customer or fewer), so paging wasn't exercised."
    fi
    step "Now rotate that key in the app, then revoke the new one."
    pause "Press Enter when both are done"
    code=$(curl -s -o /dev/null -w '%{http_code}' "${auth[@]}" "$WORKER_BASE/v1/account")
    if [[ "$code" == 401 ]]; then printf '  %s✓%s old key now gets 401\n' "$GREEN" "$RESET"; else die "Old key got $code, expected 401."; fi
    unset API_KEY
    mark_done S20
  fi
fi

# ── F. E-signature (wording approved 2026-10-15, lawyer review lifted) ───
if begin S21 "E-signature: signing key"; then
  note "Wording approved as drafted on 2026-10-15 (you lifted the lawyer review)."
  if ! confirm "Turn on e-signatures now (signing key, then stages 22-24)?"; then
    defer "E-signature stages 21-24"
  else
    on_master
    ask KEY_ID "Key id for this signing key (e.g. k$(date +%Y-%m)):"
    [[ -n "$KEY_ID" ]] || KEY_ID="k$(date +%Y-%m)"
    pem="$HOME/esign-seal-$KEY_ID.pem"
    [[ -e "$pem" ]] && die "$pem already exists; pick another key id."
    (umask 077 && openssl genpkey -algorithm ed25519 -out "$pem") || die "Key generation failed."
    openssl pkey -in "$pem" -outform DER | base64 | tr -d '\n' \
      | wrangler secret put ESIGN_SEAL_PRIVATE_KEY --env "" >/dev/null || die "Setting ESIGN_SEAL_PRIVATE_KEY failed."
    printf '  %s✓ set%s Worker secret ESIGN_SEAL_PRIVATE_KEY\n' "$GREEN" "$RESET"
    PUB=$(openssl pkey -in "$pem" -pubout -outform DER | tail -c 32 | base64)
    set_toml_var ESIGN_SEAL_KEY_ID "\"$KEY_ID\""
    set_toml_var ESIGN_SEAL_PUBLIC_KEYS "'{\"$KEY_ID\":\"$PUB\"}'"
    sed -i '' "s|var PUBLISHED_KEYS = {};|var PUBLISHED_KEYS = {\"$KEY_ID\": \"$PUB\"};|" "$LEGAL/verify.html"
    printf '  %s✓ set%s PUBLISHED_KEYS in tradeready-legal/verify.html\n' "$GREEN" "$RESET"
    commit_if_changed "chore(esign): publish seal key $KEY_ID" backend-workers/wrangler.toml
    warn "The private key is at $pem. Move it somewhere offline now."
    note "Losing it only stops new seals. If it leaks, rotate to a new key id and keep the old public key listed."
    mark_done S21
  fi
fi

if begin S22 "E-signature: switch on and publish"; then
  if [[ -z "$(_existing DONE_S21 || true)" ]]; then
    defer "Switch on e-signature (needs stage 21)"
  else
    on_master
    set_toml_var ESIGN_V2 '"true"'
    commit_if_changed "chore(esign): turn on ESIGN_V2" backend-workers/wrangler.toml
    deploy_worker
    say "Now publish verify.html and the e-signature terms (§8) and privacy (§1) text."
    note "The esign spec §11.6 wording is already applied (uncommitted) in tradeready-legal, expiry sentence kept."
    step "Review it:  git -C \"$LEGAL\" diff terms.html privacy.html"
    step "Set both pages' effective dates to today."
    pause "Press Enter when that's done"
    legal_publish "Publish e-signature verify page and terms"
    open_url "$SITE/verify.html"
    note "No separate app build: the stage 19 build already sends the esign snapshot fields."
    mark_done S22
  fi
fi

if begin S23 "E-signature: require consent"; then
  if [[ -z "$(_existing DONE_S22 || true)" ]]; then
    defer "Require e-signature consent (needs stage 22)"
  else
    on_master
    set_toml_var ESIGN_REQUIRE_CONSENT '"true"'
    commit_if_changed "chore(esign): require e-signature consent" backend-workers/wrangler.toml
    deploy_worker
    mark_done S23
  fi
fi

if begin S24 "E-signature: device smoke test"; then
  if [[ -z "$(_existing DONE_S23 || true)" ]]; then
    defer "E-signature device smoke test (needs stage 23)"
  else
    say "On a real device, with an estimate link from the app:"
    step "Sign with a drawing, and again without one. Decline one."
    step "Sign using only the keyboard, and once with VoiceOver."
    step "Download the signed PDF and JSON; check the copy email arrives."
    step "Check the record on $SITE/verify.html; fetch the owner copy in the app."
    note "Rollback if anything's wrong: remove ESIGN_V2 from wrangler.toml and deploy. Sealed records stay valid."
    if confirm "All passed?"; then mark_done S24; else defer "E-signature smoke test failures (stage 24)"; fi
  fi
fi

